def _without_payload(fn: Callable) -> Callable:
    """A listener that drops the payload and calls `fn()`, async or not, so the
    pump still runs an `async def` on the loop and offloads a plain `def`."""
    if inspect.iscoroutinefunction(fn):
        async def listener(params: Any) -> Any:
            return await fn()
        return listener
    return lambda params: fn()


